<?php
require __DIR__.'/config.php'; $name=trim($_GET['market']??''); $rows=[]; $error='';
try{ensure_schema();$sql="SELECT m.name,r.result_date,r.open_panna,r.jodi,r.close_panna FROM market_results r JOIN markets m ON m.id=r.market_id";$args=[];if($name!==''){$sql.=" WHERE m.name=?";$args[]=$name;}$sql.=" ORDER BY r.result_date DESC,m.name LIMIT 1000";$st=db()->prepare($sql);$st->execute($args);$rows=$st->fetchAll();}catch(Throwable $e){$error='Database is not connected yet. Follow the Render setup guide.';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Result History</title><link rel="stylesheet" href="style.css"></head><body><header class="mast"><div class="wrap mastin"><a class="brand" href="/"><span class="mark">R</span><span><b>RESULT HUB</b><small>RESULT ARCHIVE</small></span></a><nav><a href="/">HOME</a><a href="/history.php">RESULT HISTORY</a></nav></div></header><main class="wrap"><section class="heading historyhead"><div><p class="eyebrow">ARCHIVE</p><h2><?=h($name ?: 'Result History')?></h2><p class="sub">Previously synchronized records</p></div><a class="outline" href="/">← HOME</a></section><?php if($error):?><div class="notice"><?=h($error)?></div><?php else:?><div class="tablebox"><table><thead><tr><th>DATE</th><th>MARKET</th><th>OPEN</th><th>JODI</th><th>CLOSE</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['result_date'])?></td><td><?=h($r['name'])?></td><td><?=h($r['open_panna']?:'—')?></td><td class="jodi"><?=h($r['jodi']?:'—')?></td><td><?=h($r['close_panna']?:'—')?></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><p class="empty">No historical records found.</p><?php endif;?></div><?php endif;?></main></body></html>
